const j = $input.first().json;
const brief = $('Brief EN').first().json;
const research = brief.researchEnabled === true;

// The translated page as it stood BEFORE the citation agent ran. Absent on the
// English route, where Unwrapper never executed.
let preCitation = null;
try {
  preCitation = $('Unwrapper').first().json.translatedPage || null;
} catch (error) {
  preCitation = null;
}

let page = (!research && preCitation)
  ? preCitation
  : (j.output?.citedPage || j.output?.editedPage || j.citedPage || j.editedPage || j.translatedPage || '');

if (!page) throw new Error('Page Ready: no page found. Keys: ' + Object.keys(j));

// researchEnabled false means the page ships with zero external links, on every
// route. Internal links are added later by Internal Linker and are untouched here.
if (!research) {
  page = page
    .replace(/!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)/g, '')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1')
    .replace(/<(https?:\/\/[^\s>]+)>/g, '')
    .replace(/(?<![[(])(https?:\/\/[^\s)\]]+)/g, '');
}

const wantedH1 = brief.originalH1 || brief.h1;
if (wantedH1) {
  if (/^#\s+.+$/m.test(page)) {
    page = page.replace(/^#\s+.+$/m, `# ${wantedH1}`);
  } else {
    page = `# ${wantedH1}\n\n${page}`;
  }
}

return [{ json: { page } }];

const item = $input.first().json;
const pageText = item.output?.editedPage || item.editedPage || '';

if (!pageText) {
  throw new Error('No page text found in input. Expected output.editedPage or editedPage.');
}

const cleaned = pageText
  .replace(/!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)/g, '')
  .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1')
  .replace(/<(https?:\/\/[^\s>]+)>/g, '')
  .replace(/(?<![[(])(https?:\/\/[^\s)\]]+)/g, '');

return [{ json: { editedPage: cleaned } }];
